using System.Transactions;
using AdielSystem.Application.Common;
using AdielSystem.Application.Expenses;
using AdielSystem.Application.Security;
using Npgsql;

namespace AdielSystem.Infrastructure.Expenses;
public sealed class ExpenseRepository(NpgsqlDataSource dataSource):IExpenseRepository
{
 public async Task<ExpensePageDto> ListAsync(string search,string? status,bool archived,int page,int size,CancellationToken token){await using var c=await dataSource.OpenConnectionAsync(token);const string w="deleted_at is null and (@archived=(archived_at is not null)) and (@status='' or status=@status) and (@search='' or payee ilike @search or category ilike @search or description ilike @search or quotation_number ilike @search)";var ids=new List<Guid>();await using(var q=c.CreateCommand()){q.CommandText=$"select id from public.expenses where {w} order by expense_date desc,created_at desc limit @limit offset @offset";List(q,search,status,archived,page,size);await using var r=await q.ExecuteReaderAsync(token);while(await r.ReadAsync(token))ids.Add(r.GetGuid(0));}var items=new List<ExpenseDto>();foreach(var id in ids)items.Add(await Required(c,null,id,token));await using var count=c.CreateCommand();count.CommandText=$"select count(*) from public.expenses where {w}";List(count,search,status,archived,page,size);return new(items,page,size,(long)(await count.ExecuteScalarAsync(token)??0L));}
 public async Task<ExpenseDto?> GetAsync(Guid id,CancellationToken token){await using var c=await dataSource.OpenConnectionAsync(token);return await Read(c,null,id,token);}
 public Task<ExpenseDto> CreateAsync(SaveExpenseRequest r,CurrentUser actor,CancellationToken token)=>Execute(async(c,t)=>{var link=await Resolve(c,t,r,token);var id=Guid.NewGuid();await Insert(c,t,id,r,link,actor,token);await Audit(c,t,id,"Created",r.Payee.Trim(),"Expense created.",r.Status,r.Amount,actor,token);return await Required(c,t,id,token);},token);
 public Task<ExpenseDto> UpdateAsync(Guid id,SaveExpenseRequest r,CurrentUser actor,CancellationToken token)=>Execute(async(c,t)=>{var old=await Required(c,t,id,token);if(old.Status=="Cancelled")throw new ResourceConflictException("Cancelled expenses cannot be edited.");if(r.Status!=old.Status)throw new RequestValidationException("Use the expense status action to change status.");var link=await Resolve(c,t,r,token);await using var q=c.CreateCommand();q.Transaction=t;q.CommandText="update public.expenses set expense_date=@date,payee=@payee,category=@category,description=@description,amount=@amount,payment_method=@method,purchaser=@purchaser,status=@status,invoice_url=@invoice,notes=@notes,quotation_id=@qid,quotation_number=@qnum,project_name=@project,purchase_order_id=@po,updated_by=@actor where id=@id and archived_at is null and deleted_at is null and version=@version returning id";Params(q,id,r,link,actor.Id);q.Parameters.AddWithValue("version",r.Version!.Value);if(await q.ExecuteScalarAsync(token)is null)throw Stale();await Audit(c,t,id,"Updated",r.Payee.Trim(),"Expense updated.",r.Status,r.Amount,actor,token);return await Required(c,t,id,token);},token);
 public Task<ExpenseDto> ChangeStatusAsync(Guid id,ChangeExpenseStatusRequest r,CurrentUser actor,CancellationToken token)=>Execute(async(c,t)=>{var old=await Required(c,t,id,token);var target=r.Status.Trim();ValidTransition(old.Status,target,r.Reason);await using var q=c.CreateCommand();q.Transaction=t;q.CommandText="update public.expenses set status=@status,voided_at=case when @status='Cancelled' then now() else voided_at end,voided_by=case when @status='Cancelled' then @actor else voided_by end,void_reason=case when @status='Cancelled' then @reason else void_reason end,updated_by=@actor where id=@id and archived_at is null and deleted_at is null and version=@version returning id";q.Parameters.AddWithValue("id",id);q.Parameters.AddWithValue("status",target);q.Parameters.AddWithValue("reason",(object?)r.Reason?.Trim()??DBNull.Value);q.Parameters.AddWithValue("actor",actor.Id);q.Parameters.AddWithValue("version",r.Version);if(await q.ExecuteScalarAsync(token)is null)throw Stale();await Audit(c,t,id,target=="Cancelled"?"Voided":"Status changed",old.Payee,target=="Cancelled"?$"Expense voided: {r.Reason?.Trim()}":$"Expense status changed from {old.Status} to {target}.",target,old.Amount,actor,token);var result=await Required(c,t,id,token);if(r.ArchiveAfterVoiding)return await ArchiveInner(c,t,result,new(result.Version),true,actor,token);return result;},token);
 public Task<ExpenseDto> SetArchivedAsync(Guid id,ChangeExpenseArchiveRequest r,bool archived,CurrentUser actor,CancellationToken token)=>Execute(async(c,t)=>await ArchiveInner(c,t,await Required(c,t,id,token),r,archived,actor,token),token);
 public Task<ExpenseDto> GenerateFromPurchaseOrderAsync(Guid poId,CurrentUser actor,CancellationToken token)=>Execute(async(c,t)=>{await using(var existing=c.CreateCommand()){existing.Transaction=t;existing.CommandText="select id from public.expenses where purchase_order_id=@id and deleted_at is null";existing.Parameters.AddWithValue("id",poId);var found=await existing.ExecuteScalarAsync(token);if(found is Guid existingId)return await Required(c,t,existingId,token);}PurchaseRow po;await using(var q=c.CreateCommand()){q.Transaction=t;q.CommandText="select id,order_date,supplier_name,subject,total_amount,payment_method,quotation_id,quotation_number,client_name,payment_status from public.purchase_orders where id=@id and archived_at is null and deleted_at is null";q.Parameters.AddWithValue("id",poId);await using var r=await q.ExecuteReaderAsync(token);if(!await r.ReadAsync(token))throw new RequestValidationException("Choose an active purchase order.");po=new(r.GetGuid(0),r.GetFieldValue<DateOnly>(1),r.GetString(2),r.GetString(3),r.GetDecimal(4),r.GetString(5),r.IsDBNull(6)?null:r.GetGuid(6),r.GetString(7),r.GetString(8),r.GetString(9));}var category=await ActiveOption(c,t,"expense_category","Materials",token);var method=await ActiveOption(c,t,"payment_method",po.PaymentMethod,token);var status=po.PaymentStatus=="Paid"?"Paid":po.PaymentStatus=="Overdue"?"Overdue":"To pay";var req=new SaveExpenseRequest(po.Date,po.Supplier,category,$"Purchase Order {po.Id}",po.Total,method,actor.Username,status,null,$"PO ID: {po.Id}",po.QuotationId,po.QuotationNumber,po.Subject.Length>0?po.Subject:po.Client,po.Id);var link=new Link(po.QuotationId,po.QuotationNumber,req.ProjectName??string.Empty,po.Id);var id=Guid.NewGuid();await Insert(c,t,id,req,link,actor,token);await Audit(c,t,id,"Created",po.Supplier,$"Expense generated from purchase order {po.Id}.",status,po.Total,actor,token);return await Required(c,t,id,token);},token);
 private static async Task<ExpenseDto> ArchiveInner(NpgsqlConnection c,NpgsqlTransaction? t,ExpenseDto old,ChangeExpenseArchiveRequest r,bool archived,CurrentUser actor,CancellationToken token){if(r.Version<=0)throw new RequestValidationException("The current expense version is required.");await using var q=c.CreateCommand();q.Transaction=t;q.CommandText=archived?"update public.expenses set archived_at=now(),archived_by=@actor,updated_by=@actor where id=@id and archived_at is null and deleted_at is null and version=@version returning id":"update public.expenses set archived_at=null,archived_by=null,updated_by=@actor where id=@id and archived_at is not null and deleted_at is null and version=@version returning id";q.Parameters.AddWithValue("id",old.Id);q.Parameters.AddWithValue("actor",actor.Id);q.Parameters.AddWithValue("version",r.Version);if(await q.ExecuteScalarAsync(token)is null)throw Stale();await Audit(c,t,old.Id,archived?"Archived":"Restored",old.Payee,archived?"Expense archived.":"Expense restored.",old.Status,old.Amount,actor,token);return await Required(c,t,old.Id,token);}
 private static async Task Insert(NpgsqlConnection c,NpgsqlTransaction? t,Guid id,SaveExpenseRequest r,Link link,CurrentUser actor,CancellationToken token){await using var q=c.CreateCommand();q.Transaction=t;q.CommandText="insert into public.expenses(id,expense_date,payee,category,description,amount,payment_method,purchaser,status,invoice_url,notes,quotation_id,quotation_number,project_name,purchase_order_id,created_by,updated_by) values(@id,@date,@payee,@category,@description,@amount,@method,@purchaser,@status,@invoice,@notes,@qid,@qnum,@project,@po,@actor,@actor)";Params(q,id,r,link,actor.Id);await q.ExecuteNonQueryAsync(token);}
 private static async Task<Link> Resolve(NpgsqlConnection c,NpgsqlTransaction? t,SaveExpenseRequest r,CancellationToken token){await ActiveOption(c,t,"expense_category",r.Category,token);await ActiveOption(c,t,"payment_method",r.PaymentMethod,token);if(r.PurchaseOrderId is not null)throw new RequestValidationException("Purchase-order expenses must be generated through the purchase order endpoint.");if(r.QuotationId is null)return new(null,string.Empty,r.ProjectName?.Trim()??string.Empty,null);await using var q=c.CreateCommand();q.Transaction=t;q.CommandText="select id,quotation_number,subject,client_name from public.quotations where id=@id and status='Approved' and archived_at is null and deleted_at is null";q.Parameters.AddWithValue("id",r.QuotationId.Value);await using var x=await q.ExecuteReaderAsync(token);if(!await x.ReadAsync(token))throw new RequestValidationException("Choose an approved quotation.");return new(x.GetGuid(0),x.GetString(1),x.GetString(2).Length>0?x.GetString(2):x.GetString(3),null);}
 private static async Task<string> ActiveOption(NpgsqlConnection c,NpgsqlTransaction? t,string type,string requested,CancellationToken token){await using var q=c.CreateCommand();q.Transaction=t;q.CommandText="select name from public.business_options where option_type=@type and lower(name)=lower(@name) and is_active";q.Parameters.AddWithValue("type",type);q.Parameters.AddWithValue("name",requested.Trim());var value=await q.ExecuteScalarAsync(token) as string;return value??throw new RequestValidationException($"Choose an active {type.Replace('_',' ')}.");}
 private static async Task<ExpenseDto?> Read(NpgsqlConnection c,NpgsqlTransaction? t,Guid id,CancellationToken token){await using var q=c.CreateCommand();q.Transaction=t;q.CommandText="select id,expense_date,payee,category,description,amount,payment_method,purchaser,status,invoice_url,notes,quotation_id,quotation_number,project_name,purchase_order_id,void_reason,created_at,updated_at,archived_at,version from public.expenses where id=@id and deleted_at is null";q.Parameters.AddWithValue("id",id);await using var r=await q.ExecuteReaderAsync(token);return await r.ReadAsync(token)?new(r.GetGuid(0),r.GetFieldValue<DateOnly>(1),r.GetString(2),r.GetString(3),r.GetString(4),r.GetDecimal(5),r.GetString(6),r.GetString(7),r.GetString(8),r.IsDBNull(9)?string.Empty:r.GetString(9),r.GetString(10),r.IsDBNull(11)?null:r.GetGuid(11),r.GetString(12),r.GetString(13),r.IsDBNull(14)?null:r.GetGuid(14),r.IsDBNull(15)?null:r.GetString(15),r.GetFieldValue<DateTimeOffset>(16),r.GetFieldValue<DateTimeOffset>(17),r.IsDBNull(18)?null:r.GetFieldValue<DateTimeOffset>(18),r.GetInt64(19)):null;}
 private static async Task<ExpenseDto> Required(NpgsqlConnection c,NpgsqlTransaction? t,Guid id,CancellationToken token)=>await Read(c,t,id,token)??throw new ResourceNotFoundException($"Expense '{id}' was not found.");
 private static void Params(NpgsqlCommand q,Guid id,SaveExpenseRequest r,Link l,Guid actor){q.Parameters.AddWithValue("id",id);q.Parameters.AddWithValue("date",r.ExpenseDate);q.Parameters.AddWithValue("payee",r.Payee.Trim());q.Parameters.AddWithValue("category",r.Category.Trim());q.Parameters.AddWithValue("description",r.Description?.Trim()??string.Empty);q.Parameters.AddWithValue("amount",r.Amount);q.Parameters.AddWithValue("method",r.PaymentMethod.Trim());q.Parameters.AddWithValue("purchaser",r.Purchaser?.Trim()??string.Empty);q.Parameters.AddWithValue("status",r.Status.Trim());q.Parameters.AddWithValue("invoice",string.IsNullOrWhiteSpace(r.InvoiceUrl)?DBNull.Value:r.InvoiceUrl.Trim());q.Parameters.AddWithValue("notes",r.Notes?.Trim()??string.Empty);q.Parameters.AddWithValue("qid",(object?)l.QuotationId??DBNull.Value);q.Parameters.AddWithValue("qnum",l.QuotationNumber);q.Parameters.AddWithValue("project",l.Project);q.Parameters.AddWithValue("po",(object?)l.PurchaseOrderId??DBNull.Value);q.Parameters.AddWithValue("actor",actor);}
 private static void List(NpgsqlCommand q,string search,string? status,bool archived,int page,int size){q.Parameters.AddWithValue("archived",archived);q.Parameters.AddWithValue("status",status??string.Empty);q.Parameters.AddWithValue("search",string.IsNullOrWhiteSpace(search)?string.Empty:$"%{search}%");q.Parameters.AddWithValue("limit",size);q.Parameters.AddWithValue("offset",(page-1)*size);}
 private static async Task Audit(NpgsqlConnection c,NpgsqlTransaction? t,Guid id,string action,string entity,string description,string status,decimal amount,CurrentUser actor,CancellationToken token){await using var q=c.CreateCommand();q.Transaction=t;q.CommandText="insert into public.audit_records(record_id,module,action,entity,description,actor_id,actor_name,tone,amount,status) values(@id,'Expenses',@action,@entity,@description,@actor,@name,@tone,@amount,@status)";q.Parameters.AddWithValue("id",id);q.Parameters.AddWithValue("action",action);q.Parameters.AddWithValue("entity",entity);q.Parameters.AddWithValue("description",description);q.Parameters.AddWithValue("actor",actor.Id);q.Parameters.AddWithValue("name",actor.Username);q.Parameters.AddWithValue("tone",action is "Created"?"success":action is "Voided"?"danger":"info");q.Parameters.AddWithValue("amount",amount);q.Parameters.AddWithValue("status",status);await q.ExecuteNonQueryAsync(token);}
 private async Task<T> Execute<T>(Func<NpgsqlConnection,NpgsqlTransaction?,Task<T>> action,CancellationToken token){await using var c=await dataSource.OpenConnectionAsync(token);await using var t=Transaction.Current is null?await c.BeginTransactionAsync(token):null;var value=await action(c,t);if(t is not null)await t.CommitAsync(token);return value;}
 private static void ValidTransition(string current,string target,string? reason){if(target is not ("Paid" or "Verifying" or "To pay" or "Overdue" or "Cancelled"))throw new RequestValidationException("Expense status is invalid.");if(current=="Cancelled")throw new ResourceConflictException("Cancelled expenses cannot change status.");if(target=="Cancelled"&&string.IsNullOrWhiteSpace(reason))throw new RequestValidationException("A void reason is required.");}private static ConcurrencyConflictException Stale()=>new("This expense changed after you opened it. Reload and try again.");private sealed record Link(Guid? QuotationId,string QuotationNumber,string Project,Guid? PurchaseOrderId);private sealed record PurchaseRow(Guid Id,DateOnly Date,string Supplier,string Subject,decimal Total,string PaymentMethod,Guid? QuotationId,string QuotationNumber,string Client,string PaymentStatus);
}
